    def numberOfWays(self, s: str, t: str, k: int) -> int:
        mod = 10**9 + 7
        n = len(s)

        # Check if t is in ss (s concatenated with itself)
        ss = s + s
        if t not in ss:
            return 0

        # Check if s equals t
        if s == t:
            f0 = 1
        else:
            f0 = 0

        # Find the first occurrence of s in ss starting from index 1
        r = ss.find(s, 1)
        f1 = r - f0

        # Determine left based on whether k is even or odd
        if k % 2 == 0:
            left = f0
        else:
            left = f1

        # Determine a1 based on whether k is even or odd
        if k % 2 == 0:
            a1 = (n - 2) * r
        else:
            a1 = (n - 2) * (n - 1) * r

        # Calculate q
        q = (n - 1) ** 2

        # Calculate ans based on whether q equals 1
        if q == 1:
            ans = (a1 * (k // 2) + left) % mod
        else:
            ans = a1 * pow(q, k // 2, mod) % mod + left
            ans %= mod

        return ans % mod

